def extrair_campos_api(resposta):
    dados = resposta['dados']
    itens = []
    for item in dados['itens']:
        itens.append({
            'id': item['id'],
            'nome': item['nome'],
            'valor': item['valor']
        })
    return {
        'status': resposta['status'],
        'itens': itens
    }
